function solve(arr) {
  // Anggap elemen pertama sebagai yang terbesar untuk sementara.
  let terbesar = arr[0]
  // Periksa sisanya satu per satu; ganti jika ada yang lebih besar.
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] > terbesar) terbesar = arr[i]
  }
  return terbesar
}
